58:                        ->label(__('Name'))
59:                        ->maxLength(255),
60:                    Textarea::make('description')
61:                        ->label(__('Description'))
62:                        ->maxLength(255),
63:
64:                    Radio::make('type')
65:                        ->required()
66:                        ->label(__('Type'))
67:                        ->options([
68:                            DiscountConstants::TYPE_FIXED => __('Fixed amount'),
69:                            DiscountConstants::TYPE_PERCENTAGE => __('Percentage (of the total price)'),
70:                        ])
71:                        ->default('fixed'),
72:
73:                    Grid::make()->schema([
74:                        TextInput::make('amount')
75:                            ->label(__('Amount'))
76:                            ->helperText(__('If you choose percentage, enter a number between 0 and 100. For example: 90 for 90%. For fixed amount, enter the amount in cents. For example: 1000 for $10.00'))
77:                            ->integer()
78:                            ->required(),
79:                        DateTimePicker::make('valid_until'),
80:                    ]),
81:                    Grid::make(2)->schema([
82:                        Toggle::make('is_enabled_for_all_plans')
83:                            ->label(__('Enabled for all plans'))
84:                            ->helperText(__('If enabled, this discount will be applied to all plans. If disabled, you can select specific plans.'))
85:                            ->live(),
86:                        Select::make('plans')
87:                            ->multiple()
88:                            ->label(__('Plans'))
89:                            ->disabled(function (Get $get) {
90:                                return $get('is_enabled_for_all_plans') === true;
91:                            })
92:                            ->relationship('plans', 'name', modifyQueryUsing: function (Builder $query) {
93:                                return $query->select('plans.id', 'plans.name')->distinct();
94:                            })
95:                            ->preload()
96:                            ->helperText(__('Select the plans that this discount will be applied to.')),
97:                        Toggle::make('is_enabled_for_all_one_time_products')
98:                            ->label(__('Enabled for all one-time products'))
99:                            ->helperText(__('If enabled, this discount will be applied to all one-time products. If disabled, you can select specific one-time products.'))
100:                            ->live(),
101:                        Select::make('oneTimeProducts')
102:                            ->label(__('One-time purchase products'))
103:                            ->multiple()
104:                            ->relationship('oneTimeProducts', 'name', modifyQueryUsing: function (Builder $query) {
105:                                return $query->select('one_time_products.id', 'one_time_products.name')->distinct();
106:                            })
107:                            ->disabled(function (Get $get) {
108:                                return $get('is_enabled_for_all_one_time_products') === true;
109:                            })
110:                            ->preload()
111:                            ->helperText(__('Select the one-time products that this discount will be applied to.')),
112:                    ]),
113:                    //                    Forms\Components\Select::make('action_type')  // TODO: implement this in the future
114:                    //                        ->options(DiscountConstants::ACTION_TYPES)
115:                    //                        // change the default value to null
116:                    //                        ->default(null),
117:                    TextInput::make('max_redemptions')
118:                        ->label(__('Maximum Redemptions'))
119:                        ->integer()
120:                        ->default(-1)
121:                        ->helperText(__('Enter -1 for unlimited redemptions (total).')),
122:                    TextInput::make('max_redemptions_per_user')
123:                        ->label(__('Maximum Redemptions Per User'))
124:                        ->integer()
125:                        ->default(-1)
126:                        ->helperText(__('Enter -1 for unlimited redemptions per user.')),
127:                    Toggle::make('is_recurring')
128:                        ->label(__('Is Recurring?'))
129:                        ->helperText(__('If enabled, this discount will keep being applied to the subscription forever (or until valid if you set maximum valid date).'))
130:                        ->required(),
131:                    Toggle::make('is_active')
132:                        ->label(__('Active'))
133:                        ->default(true)
134:                        ->required(),
135:                    TextInput::make('duration_in_months')
136:                        ->label(__('Duration in Months'))
137:                        ->integer()
