141:                        ->label(__('Maximum Recurring Intervals'))
142:                        ->integer()
143:                        ->helperText(__('Amount of subscription billing periods that this discount recurs for. Only works with payment providers that support this feature. (like Paddle)'))
144:                        ->default(null),
145:
146:                ])->columnSpanFull(),
147:            ]);
148:    }
