157:                    ->sortable(),
158:                TextColumn::make('type')->label(__('Type')),
159:                TextColumn::make('amount')->label(__('Amount'))->formatStateUsing(function (string $state, $record) {
160:                    if ($record->type === DiscountConstants::TYPE_PERCENTAGE) {
