use App\Models\Discount;
use Livewire\Livewire;
use Tests\Feature\FeatureTest;

class DiscountResourceTest extends FeatureTest
{
    public function test_list(): void
    {
        $user = $this->createAdminUser();
        $this->actingAs($user);

        $response = $this->get(DiscountResource::getUrl('index', [], true, 'admin'))->assertSuccessful();

        $response->assertStatus(200);
    }

    public function test_create_discount_with_action_type_renewal(): void
    {
        $admin = $this->createAdminUser();

        Livewire::actingAs($admin)
            ->test(CreateDiscount::class)
            ->fillForm([
                'name' => 'Renewal Discount',
                'type' => DiscountConstants::TYPE_PERCENTAGE,
                'amount' => 10,
                'action_type' => DiscountConstants::ACTION_TYPE_RENEWAL,
                'max_redemptions' => -1,
                'max_redemptions_per_user' => -1,
                'is_recurring' => false,
                'is_active' => true,
            ])
            ->call('create')
            ->assertHasNoFormErrors();

        $this->assertDatabaseHas('discounts', [
            'name' => 'Renewal Discount',
            'action_type' => DiscountConstants::ACTION_TYPE_RENEWAL,
        ]);
    }

    public function test_create_discount_with_null_action_type(): void
    {
        $admin = $this->createAdminUser();

        Livewire::actingAs($admin)
            ->test(CreateDiscount::class)
            ->fillForm([
                'name' => 'Any Action Discount',
                'type' => DiscountConstants::TYPE_FIXED,
                'amount' => 500,
                'action_type' => null,
                'max_redemptions' => -1,
                'max_redemptions_per_user' => -1,
                'is_recurring' => false,
                'is_active' => true,
            ])
            ->call('create')
            ->assertHasNoFormErrors();

        $this->assertDatabaseHas('discounts', [
            'name' => 'Any Action Discount',
            'action_type' => null,
        ]);
    }

    public function test_edit_discount_action_type(): void
    {
        $admin = $this->createAdminUser();

        $discount = Discount::create([
            'name' => 'Editable Discount',
            'type' => DiscountConstants::TYPE_PERCENTAGE,
            'amount' => 15,
            'action_type' => null,
            'max_redemptions' => -1,
            'max_redemptions_per_user' => -1,
            'is_recurring' => false,
            'is_active' => true,
        ]);

        Livewire::actingAs($admin)
            ->test(EditDiscount::class, ['record' => $discount->getRouteKey()])
            ->fillForm([
                'action_type' => DiscountConstants::ACTION_TYPE_UPGRADE,
            ])
            ->call('save')
            ->assertHasNoFormErrors();

        $this->assertSame(DiscountConstants::ACTION_TYPE_UPGRADE, $discount->fresh()->action_type);
    }
}
